	Add(KELA_SETTINGS_FEATURES_COLLECTIBLES_TRACKER_TOOLTIP, "Добавляет «Отслеживание предметов коллекционирования» в меню KelaPadUI², когда установлено дополнение «Отслеживание предметов коллекционирования»: предметы коллекционирования и предметы коллекционирования, которые оно отслеживает, с фильтрами по источнику, состоянию коллекции, категории и Премиум-тому или скрытым вручную предметам. L1 и R1 переключают страницы.", 0)
	Add(KELA_SETTINGS_FEATURES_RAIDIFICATOR, "Рейдификатор", 0)
	Add(KELA_SETTINGS_FEATURES_FIGHT_STATS, "Статистика боя", 0)
	Add(KELA_SETTINGS_FEATURES_FIGHT_STATS_TOOLTIP, "Добавляет статистику боя в меню KelaPadUI²: ваши недавние бои с уроном, DPS и HPS, а также комплекты, навыки, записи чарописи и очки героя, с которыми вы сражались. Данные боя берутся из LibCombat, который устанавливается вместе с Combat Metrics. L1 и R1 переключают страницы.", 0)
	Add(KELA_SETTINGS_FIGHT_STATS_PVE, "Записывать PvE-бои", 0)
	Add(KELA_SETTINGS_FIGHT_STATS_PVE_TOOLTIP, "Записывает каждый завершённый бой в подземельях, испытаниях и открытом мире.", 0)
	Add(KELA_SETTINGS_FIGHT_STATS_BATTLEGROUNDS, "Записывать поля боя", 0)
	Add(KELA_SETTINGS_FIGHT_STATS_BATTLEGROUNDS_TOOLTIP, "Записывает каждый матч на поле боя одной записью, которая суммируется по окончании матча. Сиродил, Имперский город, Vengeance и Джераллский перевал никогда не записываются, чтобы игра работала плавно.", 0)
	Add(KELA_SETTINGS_FIGHT_STATS_KEPT, "Сохраняемые бои", 0)
	Add(KELA_SETTINGS_FIGHT_STATS_KEPT_TOOLTIP, "Сколько боёв хранит статистика боя. Когда список заполнен, сначала удаляются обычные бои, а бои с боссами и матчи на полях сражений — в последнюю очередь. Combat Metrics ведёт собственную историю боёв со своей настройкой. Примерный объём памяти при этом значении: около <<1>>. Долгие бои и большие группы занимают больше.", 0)
	Add(KELA_SETTINGS_FEATURES_RAIDIFICATOR_TOOLTIP, "Добавляет Raidificator в меню KelaPadUI², когда установлено дополнение Raidificator: история ваших очков и достижения в подземельях, испытаниях и на арене, с фильтрами по контенту, персонажу, времени и тому, чего вам еще не хватает. L1 и R1 переключают страницы.", 0)
